package dev.industrialtechnology.client.space;
import net.minecraft.client.renderer.tileentity.TileEntitySpecialRenderer;import net.minecraft.tileentity.TileEntity;import net.minecraft.util.ResourceLocation;import dev.industrialtechnology.space.*;import org.lwjgl.opengl.GL11;
public final class LaunchFacilityRenderer extends TileEntitySpecialRenderer {
    private static final ResourceLocation TEX=new ResourceLocation("industrialtech:textures/models/shuttle_atlas.png");
    @Override public void renderTileEntityAt(TileEntity te,double x,double y,double z,float partial){TileLaunchFacility t=(TileLaunchFacility)te;if(t.phase!=2)return;GL11.glPushAttrib(GL11.GL_ALL_ATTRIB_BITS);GL11.glPushMatrix();try{GL11.glTranslated(x+.5,y,z+.5);int f=t.facing();GL11.glRotatef(f==2?180:f==4?-90:f==5?90:0,0,1,0);GL11.glEnable(GL11.GL_TEXTURE_2D);GL11.glDisable(GL11.GL_LIGHTING);GL11.glDisable(GL11.GL_CULL_FACE);GL11.glColor4f(1,1,1,1);int light=t.getWorldObj().getLightBrightnessForSkyBlocks(t.xCoord,t.yCoord+40,t.zCoord,0);net.minecraft.client.renderer.OpenGlHelper.setLightmapTextureCoords(net.minecraft.client.renderer.OpenGlHelper.lightmapTexUnit,light&65535,light>>16);bindTexture(TEX);
        if(t.clientRocket&&t.clientShuttle){GL11.glPushMatrix();GL11.glTranslated(LaunchFacilityPlan.SHIP_X,LaunchFacilityPlan.DECK,LaunchFacilityPlan.SHIP_Z);ShuttleModel.draw();GL11.glPopMatrix();}
        double progress=t.armStart<0?(t.clientRocket?0:1):Math.min(1,Math.max(0,(t.getWorldObj().getTotalWorldTime()-t.armStart+partial)/Math.max(20.0,SpaceConfig.countdown*.75)));
        for(int i=0;i<3;i++){GL11.glPushMatrix();GL11.glTranslated(25, i==0?58:i==1?66:45,-30+i*3);GL11.glRotated(-90*progress,0,1,0);ShuttleModel.girder(-26,0,-.7,0,.45,.7);ShuttleModel.girder(-26,1.2,-.7,0,1.35,-.55);ShuttleModel.girder(-26,1.2,.55,0,1.35,.7);for(int n=-25;n<=0;n+=3)ShuttleModel.girder(n,0,-.7,n+.12,1.35,-.55);GL11.glPopMatrix();}
    }finally{GL11.glPopMatrix();GL11.glPopAttrib();GL11.glColor4f(1,1,1,1);}}
}
